class Solution { private int[] arr,memo;private int d;public int maxJumps(int[] arr,int d){this.arr=arr;this.d=d;memo=new int[arr.length];int answer=0;for(int i=0;i<arr.length;i++)answer=Math.max(answer,dfs(i));return answer;}private int dfs(int index){if(memo[index]!=0)return memo[index];int best=1;for(int direction:new int[]{-1,1})for(int step=1;step<=d;step++){int next=index+direction*step;if(next<0||next>=arr.length||arr[next]>=arr[index])break;best=Math.max(best,1+dfs(next));}return memo[index]=best;} }
